<?php
require_once __DIR__.'/includes/functions.php';$slug=trim($_GET['slug']??'');$s=db()->prepare('SELECT * FROM categories WHERE slug=?');$s->execute([$slug]);$cat=$s->fetch();if(!$cat){http_response_code(404);exit('التصنيف غير موجود.');}$c=db()->prepare("SELECT COUNT(*) FROM news WHERE category_id=? AND status='published' AND deleted_at IS NULL");$c->execute([$cat['id']]);[$page,$pages,$offset]=paginate((int)$c->fetchColumn(),9);$s=db()->prepare("SELECT n.*,u.name author FROM news n LEFT JOIN users u ON u.id=n.user_id WHERE n.category_id=? AND n.status='published' AND n.deleted_at IS NULL ORDER BY n.published_at DESC LIMIT 9 OFFSET {$offset}");$s->execute([$cat['id']]);$rows=$s->fetchAll();$pageTitle=$cat['name'];$metaDescription=$cat['description'];require __DIR__.'/includes/header.php';?><div class="container py-5"><div class="mb-5"><h1 class="section-title"><?=e($cat['name'])?></h1><p class="text-secondary"><?=e($cat['description'])?></p></div><div class="row g-4"><?php foreach($rows as $a):?><div class="col-md-6 col-lg-4"><article class="news-card"><img src="<?=imageUrl($a['image'])?>"><div class="p-3"><h2 class="h5 fw-bold"><a class="text-dark text-decoration-none" href="<?=url('news.php?slug='.rawurlencode($a['slug']))?>"><?=e($a['title'])?></a></h2><p class="text-secondary small"><?=e(excerpt($a['summary']))?></p><div class="article-meta"><?=formatDate($a['published_at'])?></div></div></article></div><?php endforeach;if(!$rows):?><div class="col-12 panel p-5 text-center">لا توجد أخبار منشورة في هذا التصنيف.</div><?php endif;?></div><div class="mt-5"><?=paginationLinks($page,$pages)?></div></div><?php require __DIR__.'/includes/footer.php';?>
